// Frequency HashMap — O(n)
const s = __input.s;
const t = __input.t;
const freq = __ll.map('freq');

__ll.note(`Counting chars in s="${s}"`);
for (let i = 0; i < s.length; i++) {
  __ll.setVar('i', i);
  __ll.setVar('char', s[i]);
  const cur = freq.get(s[i]) || 0;
  freq.set(s[i], cur + 1);
}

__ll.note(`Decrementing with t="${t}"`);
for (let i = 0; i < t.length; i++) {
  __ll.setVar('i', i);
  __ll.setVar('char', t[i]);
  const cur = freq.get(t[i]) || 0;
  if (cur === 0) {
    __ll.note(`'${t[i]}' not found — not an anagram`);
    return false;
  }
  freq.set(t[i], cur - 1);
}

__ll.note('Valid anagram!');
return true;

// Brute Force Sorting C++ — O(n log n)
if (s.length() != t.length()) {
  cout << "Lengths differ, not an anagram" << endl;
  return 0;
}

for (int i = 0; i < s.length(); i++) {
  for (int j = i + 1; j < s.length(); j++) {
    if (s[i] > s[j]) { char temp = s[i]; s[i] = s[j]; s[j] = temp; }
  }
}
for (int i = 0; i < t.length(); i++) {
  for (int j = i + 1; j < t.length(); j++) {
    if (t[i] > t[j]) { char temp = t[i]; t[i] = t[j]; t[j] = temp; }
  }
}

for (int i = 0; i < s.length(); i++) {
  if (s[i] != t[i]) {
    cout << "Mismatch found" << endl;
    return 0;
  }
}

cout << "Valid anagram!" << endl;
return 0;
